INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-manali-3-20',
        'มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ มะนาลี (เวทหิมาลัย)',
        'The Golden Relic Stupa of Manali (เวทหิมาลัย)',
        'sacred',
        'หิมาจัลประเทศ (อินเดีย)',
        'Himachal Pradesh (India)',
        'มะนาลี',
        'Manali',
        32.2846,
        77.2037,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน หิมาจัลประเทศ (อินเดีย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เวทหิมาลัย เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Himachal Pradesh (India), serving as the spiritual heart of ancestral เวทหิมาลัย heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค หิมาจัลประเทศ (อินเดีย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Himachal Pradesh (India), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน มะนาลี',
        'Remove footwear and maintain silence within the inner terrace of Manali.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ มะนาลี (เวทหิมาลัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-manali-3-20',
        'วิญญาณสตรีชุดขาวแห่งเส้นทางโบราณ มะนาลี (เวทหิมาลัย)',
        'The White Lady Specter of Manali (เวทหิมาลัย)',
        'ghost',
        'หิมาจัลประเทศ (อินเดีย)',
        'Himachal Pradesh (India)',
        'มะนาลี',
        'Manali',
        32.2846,
        77.2037,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น หิมาจัลประเทศ (อินเดีย) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ มะนาลี',
        'A chilling paranormal account from Himachal Pradesh (India). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Manali.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว เวทหิมาลัย ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of เวทหิมาลัย oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ มะนาลี',
        'Never whistle or look back if hearing whispers along twilight pathways in Manali.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"วิญญาณสตรีชุดขาวแห่งเส้นทางโบราณ มะนาลี (เวทหิมาลัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-manali-3-20',
        'อสุรกายพญาเงาแห่งพงไพร มะนาลี (เวทหิมาลัย)',
        'The Shadow Beast of Manali (เวทหิมาลัย)',
        'monster',
        'หิมาจัลประเทศ (อินเดีย)',
        'Himachal Pradesh (India)',
        'มะนาลี',
        'Manali',
        32.2846,
        77.2037,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน หิมาจัลประเทศ (อินเดีย) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ มะนาลี',
        'Eyewitness reports of a formidable cryptid stalking Himachal Pradesh (India). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Manali.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว เวทหิมาลัย ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native เวทหิมาลัย folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ มะนาลี',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Manali.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"อสุรกายพญาเงาแห่งพงไพร มะนาลี (เวทหิมาลัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-manali-3-20',
        'คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม มะนาลี (เวทหิมาลัย)',
        'The Inscribed Hex and Tragic Fate of Manali (เวทหิมาลัย)',
        'curse',
        'หิมาจัลประเทศ (อินเดีย)',
        'Himachal Pradesh (India)',
        'มะนาลี',
        'Manali',
        32.2846,
        77.2037,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง หิมาจัลประเทศ (อินเดีย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน มะนาลี',
        'A grim cautionary curse chronicle from Himachal Pradesh (India). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Manali.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว เวทหิมาลัย เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of เวทหิมาลัย, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ มะนาลี',
        'Never remove stones, relics, or votive offerings from Manali.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"คำสาปศิลาจารึกและอาถรรพ์ชะตากรรม มะนาลี (เวทหิมาลัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-manali-3-20',
        'มหาปราการหินเมกะลิธและแนวสุริยะ มะนาลี (เวทหิมาลัย)',
        'The Megalithic Solar Alignments of Manali (เวทหิมาลัย)',
        'legend',
        'หิมาจัลประเทศ (อินเดีย)',
        'Himachal Pradesh (India)',
        'มะนาลี',
        'Manali',
        32.2846,
        77.2037,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง หิมาจัลประเทศ (อินเดีย) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว เวทหิมาลัย ใน มะนาลี',
        'A legendary monumental marvel in Himachal Pradesh (India). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral เวทหิมาลัย engineers in Manali.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ หิมาจัลประเทศ (อินเดีย) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Himachal Pradesh (India), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ มะนาลี',
        'Do not deface, carve, or displace ancient stones in Manali.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"มหาปราการหินเมกะลิธและแนวสุริยะ มะนาลี (เวทหิมาลัย)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

