INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-jaipur-3-21',
        'พญานาคินทร์หรือสัตว์ร้ายแห่งสายน้ำลึก ชัยปุระ (ราชปุต)',
        'The Serpentine Deep Water Leviathan of Jaipur (ราชปุต)',
        'monster',
        'ราชสถาน (อินเดีย)',
        'Rajasthan (India)',
        'ชัยปุระ',
        'Jaipur',
        26.8674,
        75.7423,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน ราชสถาน (อินเดีย) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ ชัยปุระ',
        'Eyewitness reports of a formidable cryptid stalking Rajasthan (India). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Jaipur.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ราชปุต ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ราชปุต folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ ชัยปุระ',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Jaipur.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"พญานาคินทร์หรือสัตว์ร้ายแห่งสายน้ำลึก ชัยปุระ (ราชปุต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-jaipur-3-21',
        'วัตถุโบราณต้องสาปแห่งตระกูลขุนนาง ชัยปุระ (ราชปุต)',
        'The Cursed Heirlooms and Bloodline Hex of Jaipur (ราชปุต)',
        'curse',
        'ราชสถาน (อินเดีย)',
        'Rajasthan (India)',
        'ชัยปุระ',
        'Jaipur',
        26.8674,
        75.7423,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง ราชสถาน (อินเดีย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน ชัยปุระ',
        'A grim cautionary curse chronicle from Rajasthan (India). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Jaipur.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ราชปุต เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ราชปุต, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ ชัยปุระ',
        'Never remove stones, relics, or votive offerings from Jaipur.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"วัตถุโบราณต้องสาปแห่งตระกูลขุนนาง ชัยปุระ (ราชปุต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
