        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-inverness-3-23',
        'คำสาปแผ่นดินและเมืองร้างโบราณ อินเวอร์เนสส์ (เกลิกสกอต)',
        'The Desolation Curse of Inverness (เกลิกสกอต)',
        'curse',
        'ไฮแลนด์ (สกอตแลนด์)',
        'Highlands (Scotland)',
        'อินเวอร์เนสส์',
        'Inverness',
        57.4628,
        -4.1797,
        'creepy_wind',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง ไฮแลนด์ (สกอตแลนด์) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน อินเวอร์เนสส์',
        'A grim cautionary curse chronicle from Highlands (Scotland). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Inverness.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว เกลิกสกอต เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of เกลิกสกอต, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ อินเวอร์เนสส์',
        'Never remove stones, relics, or votive offerings from Inverness.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"คำสาปแผ่นดินและเมืองร้างโบราณ อินเวอร์เนสส์ (เกลิกสกอต)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

