        'pin-curse-york-3-24',
        'กระจกเงาต้องคำสาปและเงาลวงตา ยอร์ก (ไวกิ้งยอร์วิก)',
        'The Cursed Scrying Glass of York (ไวกิ้งยอร์วิก)',
        'curse',
        'ยอร์กเชียร์ (อังกฤษ)',
        'Yorkshire (England)',
        'ยอร์ก',
        'York',
        53.9591,
        -1.0965,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง ยอร์กเชียร์ (อังกฤษ) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน ยอร์ก',
        'A grim cautionary curse chronicle from Yorkshire (England). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout York.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ไวกิ้งยอร์วิก เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ไวกิ้งยอร์วิก, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ ยอร์ก',
        'Never remove stones, relics, or votive offerings from York.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"กระจกเงาต้องคำสาปและเงาลวงตา ยอร์ก (ไวกิ้งยอร์วิก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

