INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-penzance-3-25',
        'ปีศาจจำแลงร่างล่อลวงคนเดินทาง เพนแซนซ์ (เซลติกบริตัน)',
        'The Deceptive Shapeshifting Stalker of Penzance (เซลติกบริตัน)',
        'monster',
        'คอร์นวอลล์ (อังกฤษ)',
        'Cornwall (England)',
        'เพนแซนซ์',
        'Penzance',
        50.1336,
        -5.5072,
        'whisper',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน คอร์นวอลล์ (อังกฤษ) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ เพนแซนซ์',
        'Eyewitness reports of a formidable cryptid stalking Cornwall (England). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Penzance.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว เซลติกบริตัน ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native เซลติกบริตัน folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ เพนแซนซ์',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Penzance.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg","title":"ปีศาจจำแลงร่างล่อลวงคนเดินทาง เพนแซนซ์ (เซลติกบริตัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8W-DjTLd0mo","title":"สารคดี สัตว์ประหลาดในตำนานและสิ่งลี้ลับ","thumbnail":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-penzance-3-25',
        'อาถรรพ์เรือวิญญาณและกะลาสีต้องสาป เพนแซนซ์ (เซลติกบริตัน)',
        'The Spectral Vessel Curse of Penzance (เซลติกบริตัน)',
        'curse',
        'คอร์นวอลล์ (อังกฤษ)',
        'Cornwall (England)',
        'เพนแซนซ์',
        'Penzance',
        50.1336,
        -5.5072,
        'water_spirit',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง คอร์นวอลล์ (อังกฤษ) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน เพนแซนซ์',
        'A grim cautionary curse chronicle from Cornwall (England). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Penzance.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว เซลติกบริตัน เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of เซลติกบริตัน, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ เพนแซนซ์',
        'Never remove stones, relics, or votive offerings from Penzance.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"อาถรรพ์เรือวิญญาณและกะลาสีต้องสาป เพนแซนซ์ (เซลติกบริตัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-penzance-3-25',
        'กำแพงศิลาและป้อมปราการแห่งกษัตริย์ เพนแซนซ์ (เซลติกบริตัน)',
        'The Cyclopean Stone Fortresses of Penzance (เซลติกบริตัน)',
        'legend',
        'คอร์นวอลล์ (อังกฤษ)',
        'Cornwall (England)',
        'เพนแซนซ์',
        'Penzance',
        50.1336,
        -5.5072,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง คอร์นวอลล์ (อังกฤษ) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว เซลติกบริตัน ใน เพนแซนซ์',
        'A legendary monumental marvel in Cornwall (England). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral เซลติกบริตัน engineers in Penzance.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ คอร์นวอลล์ (อังกฤษ) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Cornwall (England), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ เพนแซนซ์',
        'Do not deface, carve, or displace ancient stones in Penzance.',
        'https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg","title":"กำแพงศิลาและป้อมปราการแห่งกษัตริย์ เพนแซนซ์ (เซลติกบริตัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qD-80cmvTts","title":"มรดกตำนานและนครสาบสูญแห่งประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
