        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-curragh-3-26',
        'พระธาตุยอดเขาพันยอด เคอร์ราห์ (เกลิกไอริช)',
        'The Thousand-Spire Mountain Pagoda of Curragh (เกลิกไอริช)',
        'sacred',
        'เคาน์ตีคิลแดร์ (ไอร์แลนด์)',
        'County Kildare (Ireland)',
        'เคอร์ราห์',
        'Curragh',
        53.1889,
        -6.8594,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน เคาน์ตีคิลแดร์ (ไอร์แลนด์) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เกลิกไอริช เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of County Kildare (Ireland), serving as the spiritual heart of ancestral เกลิกไอริช heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค เคาน์ตีคิลแดร์ (ไอร์แลนด์) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in County Kildare (Ireland), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน เคอร์ราห์',
        'Remove footwear and maintain silence within the inner terrace of Curragh.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"พระธาตุยอดเขาพันยอด เคอร์ราห์ (เกลิกไอริช)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

