      ) VALUES (
        'pin-curse-curragh-3-26',
        'คำสาปโลงศพและมัมมี่ผู้ล่วงละเมิด เคอร์ราห์ (เกลิกไอริช)',
        'The Desecrated Tomb Hex of Curragh (เกลิกไอริช)',
