        'County Kildare (Ireland)',
        'เคอร์ราห์',
        'Curragh',
        53.1889,
        -6.8594,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เคาน์ตีคิลแดร์ (ไอร์แลนด์) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน เคอร์ราห์',
        'A grim cautionary curse chronicle from County Kildare (Ireland). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Curragh.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว เกลิกไอริช เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of เกลิกไอริช, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ เคอร์ราห์',
        'Never remove stones, relics, or votive offerings from Curragh.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"คำสาปโลงศพและมัมมี่ผู้ล่วงละเมิด เคอร์ราห์ (เกลิกไอริช)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-curragh-3-26',
        'บ่อน้ำพุศักดิ์สิทธิ์ไร้ก้นแห่งตำนาน เคอร์ราห์ (เกลิกไอริช)',
        'The Bottomless Sacred Cenote of Curragh (เกลิกไอริช)',
        'legend',
        'เคาน์ตีคิลแดร์ (ไอร์แลนด์)',
        'County Kildare (Ireland)',
        'เคอร์ราห์',
        'Curragh',
        53.1889,
        -6.8594,
        'water_spirit',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง เคาน์ตีคิลแดร์ (ไอร์แลนด์) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว เกลิกไอริช ใน เคอร์ราห์',
        'A legendary monumental marvel in County Kildare (Ireland). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral เกลิกไอริช engineers in Curragh.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ เคาน์ตีคิลแดร์ (ไอร์แลนด์) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in County Kildare (Ireland), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ เคอร์ราห์',
        'Do not deface, carve, or displace ancient stones in Curragh.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"บ่อน้ำพุศักดิ์สิทธิ์ไร้ก้นแห่งตำนาน เคอร์ราห์ (เกลิกไอริช)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-snowdonia-3-27',
        'เทวาลัยโบราณแห่งมหาเทวะ สโนว์โดเนีย (เวลส์คิมรี)',
        'The Ancient Chola Shiva Shrine of Snowdonia (เวลส์คิมรี)',
        'sacred',
        'แคว้นเวลส์ (สหราชอาณาจักร)',
        'Wales (United Kingdom)',
        'สโนว์โดเนีย',
        'Snowdonia',
        53.1135,
        -4.0613,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน แคว้นเวลส์ (สหราชอาณาจักร) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เวลส์คิมรี เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Wales (United Kingdom), serving as the spiritual heart of ancestral เวลส์คิมรี heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค แคว้นเวลส์ (สหราชอาณาจักร) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Wales (United Kingdom), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน สโนว์โดเนีย',
        'Remove footwear and maintain silence within the inner terrace of Snowdonia.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"เทวาลัยโบราณแห่งมหาเทวะ สโนว์โดเนีย (เวลส์คิมรี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-snowdonia-3-27',
        'ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ สโนว์โดเนีย (เวลส์คิมรี)',
        'The Will-o''-the-Wisp Ghost Light of Snowdonia (เวลส์คิมรี)',
        'ghost',
        'แคว้นเวลส์ (สหราชอาณาจักร)',
        'Wales (United Kingdom)',
        'สโนว์โดเนีย',
        'Snowdonia',
        53.1135,
        -4.0613,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น แคว้นเวลส์ (สหราชอาณาจักร) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ สโนว์โดเนีย',
        'A chilling paranormal account from Wales (United Kingdom). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Snowdonia.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว เวลส์คิมรี ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of เวลส์คิมรี oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ สโนว์โดเนีย',
        'Never whistle or look back if hearing whispers along twilight pathways in Snowdonia.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"ดวงไฟวิญญาณลอยล่องกลางหนองน้ำ สโนว์โดเนีย (เวลส์คิมรี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-snowdonia-3-27',
        'อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด สโนว์โดเนีย (เวลส์คิมรี)',
        'The Amphibious Troglodyte of Snowdonia (เวลส์คิมรี)',
        'monster',
        'แคว้นเวลส์ (สหราชอาณาจักร)',
        'Wales (United Kingdom)',
        'สโนว์โดเนีย',
        'Snowdonia',
        53.1135,
        -4.0613,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน แคว้นเวลส์ (สหราชอาณาจักร) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ สโนว์โดเนีย',
        'Eyewitness reports of a formidable cryptid stalking Wales (United Kingdom). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Snowdonia.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว เวลส์คิมรี ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native เวลส์คิมรี folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ สโนว์โดเนีย',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Snowdonia.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"อสูรครึ่งคนครึ่งสัตว์น้ำแห่งถ้ำมืด สโนว์โดเนีย (เวลส์คิมรี)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

