        'pin-sacred-garmisch-3-28',
        'มหารัตนเจดีย์แห่งมโนธรรม การ์มิช (บาวาเรียนแอลป์)',
        'The Great Jeweled Pagoda of Garmisch (บาวาเรียนแอลป์)',
        'sacred',
        'บาวาเรีย (เยอรมนี)',
        'Bavaria (Germany)',
        'การ์มิช',
        'Garmisch',
        47.4467,
        11.0506,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน บาวาเรีย (เยอรมนี) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว บาวาเรียนแอลป์ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Bavaria (Germany), serving as the spiritual heart of ancestral บาวาเรียนแอลป์ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค บาวาเรีย (เยอรมนี) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Bavaria (Germany), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน การ์มิช',
        'Remove footwear and maintain silence within the inner terrace of Garmisch.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"มหารัตนเจดีย์แห่งมโนธรรม การ์มิช (บาวาเรียนแอลป์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-garmisch-3-28',
        'วิญญาณคนเฝ้าประภาคารผู้ล่วงลับ การ์มิช (บาวาเรียนแอลป์)',
        'The Restless Keeper of Garmisch (บาวาเรียนแอลป์)',
        'ghost',
        'บาวาเรีย (เยอรมนี)',
        'Bavaria (Germany)',
        'การ์มิช',
        'Garmisch',
        47.4467,
        11.0506,
        'creepy_wind',
        'เรื่องเล่าสยองขวัญประจำถิ่น บาวาเรีย (เยอรมนี) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ การ์มิช',
        'A chilling paranormal account from Bavaria (Germany). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Garmisch.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว บาวาเรียนแอลป์ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of บาวาเรียนแอลป์ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ การ์มิช',
        'Never whistle or look back if hearing whispers along twilight pathways in Garmisch.',
        'https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg","title":"วิญญาณคนเฝ้าประภาคารผู้ล่วงลับ การ์มิช (บาวาเรียนแอลป์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbCWDUZhSFc","title":"ปริศนาดวงวิญญาณและคฤหาสน์ต้องห้าม","thumbnail":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-garmisch-3-28',
        'สัตว์ร้ายดูดเลือดแห่งทุ่งรกร้าง การ์มิช (บาวาเรียนแอลป์)',
        'The Night Livestock Stalker of Garmisch (บาวาเรียนแอลป์)',
        'monster',
        'บาวาเรีย (เยอรมนี)',
        'Bavaria (Germany)',
        'การ์มิช',
        'Garmisch',
        47.4467,
        11.0506,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน บาวาเรีย (เยอรมนี) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ การ์มิช',
        'Eyewitness reports of a formidable cryptid stalking Bavaria (Germany). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Garmisch.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว บาวาเรียนแอลป์ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native บาวาเรียนแอลป์ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ การ์มิช',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Garmisch.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg","title":"สัตว์ร้ายดูดเลือดแห่งทุ่งรกร้าง การ์มิช (บาวาเรียนแอลป์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8W-DjTLd0mo","title":"สารคดี สัตว์ประหลาดในตำนานและสิ่งลี้ลับ","thumbnail":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-garmisch-3-28',
        'คำสาปสะพานมรณะและลางบอกเหตุ การ์มิช (บาวาเรียนแอลป์)',
        'The Cursed Bridge Omen of Garmisch (บาวาเรียนแอลป์)',
        'curse',
        'บาวาเรีย (เยอรมนี)',
        'Bavaria (Germany)',
        'การ์มิช',
        'Garmisch',
        47.4467,
        11.0506,
        'creepy_wind',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง บาวาเรีย (เยอรมนี) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน การ์มิช',
        'A grim cautionary curse chronicle from Bavaria (Germany). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Garmisch.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว บาวาเรียนแอลป์ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of บาวาเรียนแอลป์, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ การ์มิช',
        'Never remove stones, relics, or votive offerings from Garmisch.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"คำสาปสะพานมรณะและลางบอกเหตุ การ์มิช (บาวาเรียนแอลป์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
