        7.8421,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น แบล็กฟอเรสต์ (เยอรมนี) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ ไฟรบวร์ก',
        'A chilling paranormal account from Black Forest (Germany). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Freiburg.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ป่าดำสวาเบียน ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ป่าดำสวาเบียน oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ ไฟรบวร์ก',
        'Never whistle or look back if hearing whispers along twilight pathways in Freiburg.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"เสียงฝีเท้าลี้ลับแห่งบันไดวนชั้นใต้ดิน ไฟรบวร์ก (ป่าดำสวาเบียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-freiburg-3-29',
        'พญาอสรพิษเกล็ดนิลแห่งแอ่งน้ำวน ไฟรบวร์ก (ป่าดำสวาเบียน)',
        'The Black-Scaled Serpent of Freiburg (ป่าดำสวาเบียน)',
        'monster',
        'แบล็กฟอเรสต์ (เยอรมนี)',
        'Black Forest (Germany)',
        'ไฟรบวร์ก',
        'Freiburg',
        47.969,
        7.8421,
        'water_spirit',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน แบล็กฟอเรสต์ (เยอรมนี) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ ไฟรบวร์ก',
        'Eyewitness reports of a formidable cryptid stalking Black Forest (Germany). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Freiburg.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ป่าดำสวาเบียน ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ป่าดำสวาเบียน folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ ไฟรบวร์ก',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Freiburg.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"พญาอสรพิษเกล็ดนิลแห่งแอ่งน้ำวน ไฟรบวร์ก (ป่าดำสวาเบียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-freiburg-3-29',
        'อาถรรพ์รูปเคารพและดวงตาจ้องมอง ไฟรบวร์ก (ป่าดำสวาเบียน)',
        'The Cursed Effigy Gaze of Freiburg (ป่าดำสวาเบียน)',
        'curse',
        'แบล็กฟอเรสต์ (เยอรมนี)',
        'Black Forest (Germany)',
        'ไฟรบวร์ก',
        'Freiburg',
        47.969,
        7.8421,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง แบล็กฟอเรสต์ (เยอรมนี) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน ไฟรบวร์ก',
        'A grim cautionary curse chronicle from Black Forest (Germany). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Freiburg.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ป่าดำสวาเบียน เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ป่าดำสวาเบียน, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ ไฟรบวร์ก',
        'Never remove stones, relics, or votive offerings from Freiburg.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"อาถรรพ์รูปเคารพและดวงตาจ้องมอง ไฟรบวร์ก (ป่าดำสวาเบียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
