        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-freiburg-3-29',
        'รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ ไฟรบวร์ก (ป่าดำสวาเบียน)',
        'The Undeciphered Glyph Stele of Freiburg (ป่าดำสวาเบียน)',
        'legend',
        'แบล็กฟอเรสต์ (เยอรมนี)',
        'Black Forest (Germany)',
        'ไฟรบวร์ก',
        'Freiburg',
        47.969,
        7.8421,
        'whisper',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง แบล็กฟอเรสต์ (เยอรมนี) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ป่าดำสวาเบียน ใน ไฟรบวร์ก',
        'A legendary monumental marvel in Black Forest (Germany). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ป่าดำสวาเบียน engineers in Freiburg.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ แบล็กฟอเรสต์ (เยอรมนี) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Black Forest (Germany), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ ไฟรบวร์ก',
        'Do not deface, carve, or displace ancient stones in Freiburg.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"รอยจารึกลึกลับแห่งอารยธรรมที่สาบสูญ ไฟรบวร์ก (ป่าดำสวาเบียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

