        '[{"type":"image","url":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg","title":"นครโบราณที่สาบสูญใต้ผืนป่า อาวีญง (ออกซิตัน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=qD-80cmvTts","title":"มรดกตำนานและนครสาบสูญแห่งประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/qD-80cmvTts/hqdefault.jpg"}]'
