INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-sighisoara-4-32',
        'อารามโบราณพิทักษ์ผืนป่า ซีกีชออารา (ดราคูลาคาพาเทียน)',
        'The Sacred Mountain Hermitage of Sighisoara (ดราคูลาคาพาเทียน)',
        'sacred',
        'ทรานซิลเวเนีย (โรมาเนีย)',
        'Transylvania (Romania)',
        'ซีกีชออารา',
        'Sighisoara',
        46.2347,
        24.8233,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน ทรานซิลเวเนีย (โรมาเนีย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว ดราคูลาคาพาเทียน เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Transylvania (Romania), serving as the spiritual heart of ancestral ดราคูลาคาพาเทียน heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค ทรานซิลเวเนีย (โรมาเนีย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Transylvania (Romania), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน ซีกีชออารา',
        'Remove footwear and maintain silence within the inner terrace of Sighisoara.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"อารามโบราณพิทักษ์ผืนป่า ซีกีชออารา (ดราคูลาคาพาเทียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-sighisoara-4-32',
        'ดวงวิญญาณผู้พิทักษ์คฤหาสน์เก่า ซีกีชออารา (ดราคูลาคาพาเทียน)',
        'The Ancestral Manor Shade of Sighisoara (ดราคูลาคาพาเทียน)',
        'ghost',
        'ทรานซิลเวเนีย (โรมาเนีย)',
        'Transylvania (Romania)',
        'ซีกีชออารา',
        'Sighisoara',
        46.2347,
        24.8233,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น ทรานซิลเวเนีย (โรมาเนีย) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ ซีกีชออารา',
        'A chilling paranormal account from Transylvania (Romania). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Sighisoara.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ดราคูลาคาพาเทียน ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ดราคูลาคาพาเทียน oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ ซีกีชออารา',
        'Never whistle or look back if hearing whispers along twilight pathways in Sighisoara.',
        'https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg","title":"ดวงวิญญาณผู้พิทักษ์คฤหาสน์เก่า ซีกีชออารา (ดราคูลาคาพาเทียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XtIe-oS07gg","title":"เรื่องเล่าวิญญาณและปราสาทหลอนโบราณ","thumbnail":"https://i.ytimg.com/vi/XtIe-oS07gg/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-sighisoara-4-32',
        'อสูรมีปีกกางข้ามเวหายามค่ำ ซีกีชออารา (ดราคูลาคาพาเทียน)',
        'The Winged Night Prowler of Sighisoara (ดราคูลาคาพาเทียน)',
        'monster',
        'ทรานซิลเวเนีย (โรมาเนีย)',
        'Transylvania (Romania)',
        'ซีกีชออารา',
        'Sighisoara',
        46.2347,
        24.8233,
        'creepy_wind',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน ทรานซิลเวเนีย (โรมาเนีย) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ ซีกีชออารา',
        'Eyewitness reports of a formidable cryptid stalking Transylvania (Romania). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Sighisoara.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ดราคูลาคาพาเทียน ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ดราคูลาคาพาเทียน folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ ซีกีชออารา',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Sighisoara.',
        'https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg","title":"อสูรมีปีกกางข้ามเวหายามค่ำ ซีกีชออารา (ดราคูลาคาพาเทียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0fdreKvuqgs","title":"การค้นพบสิ่งมีชีวิตลี้ลับและอสุรกายโบราณ","thumbnail":"https://i.ytimg.com/vi/0fdreKvuqgs/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-sighisoara-4-32',
        'อาถรรพ์ทางแยกสัญญามนต์ดำ ซีกีชออารา (ดราคูลาคาพาเทียน)',
        'The Forbidden Crossroads Covenant of Sighisoara (ดราคูลาคาพาเทียน)',
        'curse',
        'ทรานซิลเวเนีย (โรมาเนีย)',
        'Transylvania (Romania)',
        'ซีกีชออารา',
        'Sighisoara',
        46.2347,
        24.8233,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง ทรานซิลเวเนีย (โรมาเนีย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน ซีกีชออารา',
        'A grim cautionary curse chronicle from Transylvania (Romania). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Sighisoara.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ดราคูลาคาพาเทียน เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ดราคูลาคาพาเทียน, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ ซีกีชออารา',
        'Never remove stones, relics, or votive offerings from Sighisoara.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"อาถรรพ์ทางแยกสัญญามนต์ดำ ซีกีชออารา (ดราคูลาคาพาเทียน)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
