        'Preserved across oral epics and excavated strata in Andalusia (Spain), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ กรานาดา',
        'Do not deface, carve, or displace ancient stones in Granada.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"กำแพงศิลาและป้อมปราการแห่งกษัตริย์ กรานาดา (มัวร์อัลอันดาลุส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-sparta-4-36',
        'พระธาตุยอดเขาพันยอด สปาร์ตา (เฮลเลนิกโบราณ)',
        'The Thousand-Spire Mountain Pagoda of Sparta (เฮลเลนิกโบราณ)',
        'sacred',
        'เพโลพอนนีส (กรีซ)',
        'Peloponnese (Greece)',
        'สปาร์ตา',
        'Sparta',
        37.0433,
        22.4297,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน เพโลพอนนีส (กรีซ) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว เฮลเลนิกโบราณ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Peloponnese (Greece), serving as the spiritual heart of ancestral เฮลเลนิกโบราณ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค เพโลพอนนีส (กรีซ) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Peloponnese (Greece), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน สปาร์ตา',
        'Remove footwear and maintain silence within the inner terrace of Sparta.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"พระธาตุยอดเขาพันยอด สปาร์ตา (เฮลเลนิกโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-sparta-4-36',
        'เสียงสะอื้นไห้ใต้สะพานหินโบราณ สปาร์ตา (เฮลเลนิกโบราณ)',
        'The Phantom Sobs Beneath Stone Bridge of Sparta (เฮลเลนิกโบราณ)',
        'ghost',
        'เพโลพอนนีส (กรีซ)',
        'Peloponnese (Greece)',
        'สปาร์ตา',
        'Sparta',
        37.0433,
        22.4297,
        'water_spirit',
        'เรื่องเล่าสยองขวัญประจำถิ่น เพโลพอนนีส (กรีซ) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ สปาร์ตา',
        'A chilling paranormal account from Peloponnese (Greece). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Sparta.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว เฮลเลนิกโบราณ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of เฮลเลนิกโบราณ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ สปาร์ตา',
        'Never whistle or look back if hearing whispers along twilight pathways in Sparta.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"เสียงสะอื้นไห้ใต้สะพานหินโบราณ สปาร์ตา (เฮลเลนิกโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-sparta-4-36',
        'อสูรกายเขี้ยวเพลิงแห่งหุบเขา สปาร์ตา (เฮลเลนิกโบราณ)',
        'The Horned Fire-Eyed Ravager of Sparta (เฮลเลนิกโบราณ)',
        'monster',
        'เพโลพอนนีส (กรีซ)',
        'Peloponnese (Greece)',
        'สปาร์ตา',
        'Sparta',
        37.0433,
        22.4297,
        'creepy_wind',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน เพโลพอนนีส (กรีซ) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ สปาร์ตา',
        'Eyewitness reports of a formidable cryptid stalking Peloponnese (Greece). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Sparta.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว เฮลเลนิกโบราณ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native เฮลเลนิกโบราณ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ สปาร์ตา',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Sparta.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"อสูรกายเขี้ยวเพลิงแห่งหุบเขา สปาร์ตา (เฮลเลนิกโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-sparta-4-36',
        'คำสาปโลงศพและมัมมี่ผู้ล่วงละเมิด สปาร์ตา (เฮลเลนิกโบราณ)',
        'The Desecrated Tomb Hex of Sparta (เฮลเลนิกโบราณ)',
        'curse',
        'เพโลพอนนีส (กรีซ)',
        'Peloponnese (Greece)',
        'สปาร์ตา',
        'Sparta',
        37.0433,
        22.4297,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เพโลพอนนีส (กรีซ) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน สปาร์ตา',
        'A grim cautionary curse chronicle from Peloponnese (Greece). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Sparta.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว เฮลเลนิกโบราณ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of เฮลเลนิกโบราณ, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ สปาร์ตา',
        'Never remove stones, relics, or votive offerings from Sparta.',
        'https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg","title":"คำสาปโลงศพและมัมมี่ผู้ล่วงละเมิด สปาร์ตา (เฮลเลนิกโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TWCWQq-YNdI","title":"คำสาปแห่งราชวงศ์และสิ่งเร้นลับทางประวัติศาสตร์","thumbnail":"https://i.ytimg.com/vi/TWCWQq-YNdI/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
