      ) VALUES (
        'pin-curse-notodden-4-38',
        'คำสาปสะพานมรณะและลางบอกเหตุ นอต็อดเดน (ไวกิ้งนอร์ส)',
        'The Cursed Bridge Omen of Notodden (ไวกิ้งนอร์ส)',
        'curse',
        'เทเลมาร์ก (นอร์เวย์)',
        'Telemark (Norway)',
        'นอต็อดเดน',
        'Notodden',
        59.5594,
        9.2436,
        'creepy_wind',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง เทเลมาร์ก (นอร์เวย์) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน นอต็อดเดน',
        'A grim cautionary curse chronicle from Telemark (Norway). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Notodden.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ไวกิ้งนอร์ส เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ไวกิ้งนอร์ส, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ นอต็อดเดน',
        'Never remove stones, relics, or votive offerings from Notodden.',
        'https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg","title":"คำสาปสะพานมรณะและลางบอกเหตุ นอต็อดเดน (ไวกิ้งนอร์ส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=j80tWn1d9a0","title":"สารคดี เรื่องลี้ลับและคำสาปโบราณ","thumbnail":"https://i.ytimg.com/vi/j80tWn1d9a0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
