        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-notodden-4-38',
        'เกาะลอยน้ำและวิหารกลางบึงโบราณ นอต็อดเดน (ไวกิ้งนอร์ส)',
        'The Artificial Floating Shrines of Notodden (ไวกิ้งนอร์ส)',
        'legend',
        'เทเลมาร์ก (นอร์เวย์)',
        'Telemark (Norway)',
        'นอต็อดเดน',
        'Notodden',
        59.5594,
        9.2436,
        'water_spirit',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง เทเลมาร์ก (นอร์เวย์) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ไวกิ้งนอร์ส ใน นอต็อดเดน',
        'A legendary monumental marvel in Telemark (Norway). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ไวกิ้งนอร์ส engineers in Notodden.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ เทเลมาร์ก (นอร์เวย์) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Telemark (Norway), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ นอต็อดเดน',
        'Do not deface, carve, or displace ancient stones in Notodden.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"เกาะลอยน้ำและวิหารกลางบึงโบราณ นอต็อดเดน (ไวกิ้งนอร์ส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
