        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-new-orleans-4-39',
        'เสียงฝีเท้าลี้ลับแห่งบันไดวนชั้นใต้ดิน นิวออร์ลีนส์ (ครีโอลวูดู)',
        'The Midnight Footsteps of New Orleans (ครีโอลวูดู)',
        'ghost',
        'ลุยเซียนา (สหรัฐอเมริกา)',
        'Louisiana (United States)',
        'นิวออร์ลีนส์',
        'New Orleans',
        29.9661,
        -90.0415,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น ลุยเซียนา (สหรัฐอเมริกา) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ นิวออร์ลีนส์',
        'A chilling paranormal account from Louisiana (United States). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of New Orleans.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว ครีโอลวูดู ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of ครีโอลวูดู oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ นิวออร์ลีนส์',
        'Never whistle or look back if hearing whispers along twilight pathways in New Orleans.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"เสียงฝีเท้าลี้ลับแห่งบันไดวนชั้นใต้ดิน นิวออร์ลีนส์ (ครีโอลวูดู)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

